describe('Faceted Search - Update Results Without Full Page Reload', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should update search results in real-time as user filters', () => {
    // Initial search results
    cy.get('[data-testid="search-results"]').should('be.visible');
    cy.get('[data-testid="result-item"]').should('have.length.greaterThan', 0);

    // Verify initial results
    cy.get('[data-testid="result-item"]').first().should('contain', 'Product A');

    // Apply first filter (Category: Electronics)
    cy.get('[data-testid="category-filter"]').click();
    cy.get('[data-testid="category-filter-option"]').click({ force: true });
    cy.get('[data-testid="category-filter-option-electronics"]').click();

    // Verify results are filtered
    cy.get('[data-testid="result-item"]').first().should('contain', 'Electronics');
    cy.get('[data-testid="result-item"]').first().should('not.contain', 'Clothing');

    // Apply second filter (Price: $500+)
    cy.get('[data-testid="price-filter"]').click();
    cy.get('[data-testid="price-filter-option"]').click({ force: true });
    cy.get('[data-testid="price-filter-option-500"]').click();

    // Verify results are further filtered
    cy.get('[data-testid="result-item"]').first().should('contain', 'Electronics');
    cy.get('[data-testid="result-item"]').first().should('contain', '$500');

    // Verify no full page reload
    cy.get('[data-testid="page-reload-indicator"]').should('not.exist');

    // Verify search results are still visible
    cy.get('[data-testid="search-results"]').should('be.visible');
  });

  it('should handle edge case where no results match filters', () => {
    // Apply filters to narrow down results
    cy.get('[data-testid="category-filter"]').click();
    cy.get('[data-testid="category-filter-option"]').click({ force: true });
    cy.get('[data-testid="category-filter-option-books"]').click();

    cy.get('[data-testid="price-filter"]').click();
    cy.get('[data-testid="price-filter-option"]').click({ force: true });
    cy.get('[data-testid="price-filter-option-10"]').click();

    // Verify no results are displayed
    cy.get('[data-testid="result-item"]').should('not.exist');

    // Verify no page reload occurs
    cy.get('[data-testid="page-reload-indicator"]').should('not.exist');

    // Verify user is presented with no results message
    cy.get('[data-testid="no-results-message"]').should('be.visible');
    cy.get('[data-testid="no-results-message"]').should('contain', 'No results found');
  });
});
